<?php
declare(strict_types=1);require_once dirname(__DIR__).'/app.php';
function post_text(string $key,int $max=255): string { return mb_substr(trim((string)($_POST[$key]??'')),0,$max); }
function business_id(): int { static $id=null;if($id!==null)return $id;$q=db()->prepare('SELECT business_id FROM users WHERE id=? AND active=1');$q->execute([current_user()['id']]);$id=(int)$q->fetchColumn();if(!$id){session_destroy();redirect('login.php');}return $id; }
function require_permission(string $key): void { $u=require_auth();if($u['role']==='owner')return;$q=db()->prepare('SELECT granted FROM user_permissions WHERE user_id=? AND permission_key=?');$q->execute([$u['id'],$key]);if(!(bool)$q->fetchColumn()){http_response_code(403);exit('You do not have permission to access this area. Ask the Owner to update your access.');} }
function module_action(string $type): void {
 if($_SERVER['REQUEST_METHOD']!=='POST')return;verify_csrf();$pdo=db();$bid=business_id();$act=(string)($_POST['action']??'create');
 $permissionMap=['customers'=>'customers','leads'=>'leads','products'=>'products','tasks'=>'tasks','quotations'=>'quotations'];if(isset($permissionMap[$type]))require_permission($permissionMap[$type].'.edit');
 if($type==='customers'){
  if($act==='archive'){$q=$pdo->prepare('UPDATE customers SET archived_at=NOW() WHERE id=? AND business_id=?');$q->execute([(int)$_POST['id'],$bid]);audit('customer.archive','Customer archived');flash('Customer archived.');return;}
  $name=post_text('name');$email=post_text('email',190);if($name==='') {flash('A customer name is required.','error');return;}
  if($act==='edit'){$q=$pdo->prepare('UPDATE customers SET name=?,company=?,email=?,phone=?,city=?,gstin=?,address=?,state=?,state_code=?,postal_code=?,notes=? WHERE id=? AND business_id=? AND archived_at IS NULL');$q->execute([$name,post_text('company'),$email?:null,post_text('phone'),post_text('city'),post_text('gstin'),post_text('address'),post_text('state'),post_text('state_code',2),post_text('postal_code',20),post_text('notes',4000),(int)$_POST['id'],$bid]);$id=(int)$_POST['id'];audit('customer.update',$name);}else{$q=$pdo->prepare('INSERT INTO customers(business_id,name,company,email,phone,city,gstin,address,state,state_code,postal_code,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$bid,$name,post_text('company'),$email?:null,post_text('phone'),post_text('city'),post_text('gstin'),post_text('address'),post_text('state'),post_text('state_code',2),post_text('postal_code',20),post_text('notes',4000)]);$id=(int)$pdo->lastInsertId();audit('customer.create',$name);}flash('Customer saved.');redirect('customers.php?view='.$id);
 }
 if($type==='leads'){
  if($act==='stage'){$q=$pdo->prepare('UPDATE leads SET stage=?,status=? WHERE id=? AND business_id=?');$stage=post_text('stage',60);$status=$stage==='Won'?'Won':($stage==='Lost'?'Lost':'Open');$q->execute([$stage,$status,(int)$_POST['id'],$bid]);audit('lead.stage',$stage);flash('Lead updated.');return;}
  $name=post_text('name');if($name===''){flash('A contact name is required.','error');return;}$val=max(0,(float)($_POST['deal_value']??0));$date=post_text('expected_close',10)?:null;$fields=[$name,post_text('company'),post_text('email',190)?:null,post_text('phone'),post_text('source',80),post_text('stage',60)?:'New',$val,$date,post_text('notes',4000)];if($act==='edit'){$q=$pdo->prepare('UPDATE leads SET name=?,company=?,email=?,phone=?,source=?,stage=?,deal_value=?,expected_close=?,notes=? WHERE id=? AND business_id=?');$q->execute([...$fields,(int)$_POST['id'],$bid]);audit('lead.update',$name);}else{$q=$pdo->prepare('INSERT INTO leads(business_id,name,company,email,phone,source,stage,deal_value,expected_close,notes) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$bid,$name,post_text('company'),post_text('email',190)?:null,post_text('phone'),post_text('source',80),post_text('stage',60)?:'New',$val,$date,post_text('notes',4000)]);audit('lead.create',$name);}flash('Lead saved.');return;
 }
 if($type==='products'){
  if($act==='archive'){$pdo->prepare('UPDATE products SET active=0 WHERE id=? AND business_id=?')->execute([(int)$_POST['id'],$bid]);audit('product.archive');flash('Item archived.');return;}
  $name=post_text('name');if($name===''){flash('An item name is required.','error');return;}$price=max(0,(float)($_POST['price']??0));$tax=max(0,min(100,(float)($_POST['tax_rate']??0)));$data=[$name,post_text('sku',80),post_text('hsn_sac',20),in_array($_POST['kind']??'', ['Product','Service'],true)?$_POST['kind']:'Service',post_text('category',100),post_text('unit',40)?:'unit',$price,$tax];if($act==='edit'){$pdo->prepare('UPDATE products SET name=?,sku=?,hsn_sac=?,kind=?,category=?,unit=?,price=?,tax_rate=? WHERE id=? AND business_id=?')->execute([...$data,(int)$_POST['id'],$bid]);audit('product.update',$name);}else{$pdo->prepare('INSERT INTO products(business_id,name,sku,hsn_sac,kind,category,unit,price,tax_rate) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$bid,...$data]);audit('product.create',$name);}flash('Item saved.');return;
 }
 if($type==='tasks'){
  if($act==='complete'){$pdo->prepare("UPDATE tasks SET status='Completed' WHERE id=? AND business_id=?")->execute([(int)$_POST['id'],$bid]);audit('task.complete');flash('Task completed.');return;}
  $title=post_text('title');if($title===''){flash('A task title is required.','error');return;}$customer=(int)($_POST['customer_id']??0)?:null;if($customer){$chk=$pdo->prepare('SELECT id FROM customers WHERE id=? AND business_id=?');$chk->execute([$customer,$bid]);if(!$chk->fetchColumn())$customer=null;}$date=post_text('due_date',10)?:null;$priority=in_array($_POST['priority']??'', ['Low','Medium','High'],true)?$_POST['priority']:'Medium';$q=$pdo->prepare('INSERT INTO tasks(business_id,customer_id,title,description,priority,due_date) VALUES(?,?,?,?,?,?)');$q->execute([$bid,$customer,$title,post_text('description',4000),$priority,$date]);audit('task.create',$title);flash('Task added.');return;
 }
 if($type==='quotations'){
  $id=(int)($_POST['id']??0);
  if($act==='status'){$status=post_text('status',20);if(!in_array($status,['Sent','Accepted','Rejected'],true)){flash('That quotation status cannot be selected.','error');return;}$q=$pdo->prepare("UPDATE quotations SET status=? WHERE id=? AND business_id=? AND status IN ('Draft','Sent','Accepted','Rejected')");$q->execute([$status,$id,$bid]);audit('quotation.status',$status.' #'.$id);flash('Quotation status updated.');return;}
  if($act==='convert'){
   try{$taxMode=$pdo->prepare('SELECT gst_registration_type FROM businesses WHERE id=?');$taxMode->execute([$bid]);if($taxMode->fetchColumn()==='Regular')throw new RuntimeException('For a GST-registered workspace, create the tax invoice from the catalog so HSN/SAC and state-wise tax are calculated correctly.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM quotations WHERE id=? AND business_id=? FOR UPDATE');$q->execute([$id,$bid]);$quote=$q->fetch();if(!$quote||$quote['status']!=='Accepted'||$quote['invoice_id'])throw new RuntimeException('Only an accepted quotation that has not already been converted can become an invoice.');$customerQ=$pdo->prepare('SELECT * FROM customers WHERE id=? AND business_id=? AND archived_at IS NULL');$customerQ->execute([$quote['customer_id'],$bid]);$customer=$customerQ->fetch();if(!$customer)throw new RuntimeException('The quotation customer is no longer active.');$businessQ=$pdo->prepare('SELECT name,currency FROM businesses WHERE id=?');$businessQ->execute([$bid]);$business=$businessQ->fetch();$invoiceNumber='INV-'.date('Y').'-'.bin2hex(random_bytes(4));$invoiceDate=date('Y-m-d');$dueDate=date('Y-m-d',strtotime('+14 days'));$pdo->prepare("INSERT INTO invoices(business_id,customer_id,invoice_number,invoice_date,due_date,status,subtotal,tax_total,total,customer_snapshot,business_snapshot,notes) VALUES(?,?,?,?,?,'Issued',?,?,?,?,?,?)")->execute([$bid,$customer['id'],$invoiceNumber,$invoiceDate,$dueDate,$quote['subtotal'],$quote['tax_total'],$quote['total'],json_encode($customer),json_encode($business),$quote['notes']]);$invoiceId=(int)$pdo->lastInsertId();$copy=$pdo->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit,unit_price,tax_rate,line_subtotal,line_tax,line_total) SELECT ?,description,quantity,unit,unit_price,tax_rate,line_subtotal,line_tax,line_total FROM quotation_items WHERE quotation_id=?');$copy->execute([$invoiceId,$id]);if($copy->rowCount()<1)throw new RuntimeException('Quotation has no line items; no invoice was created.');$pdo->prepare("UPDATE quotations SET status='Converted',invoice_id=? WHERE id=? AND business_id=? AND invoice_id IS NULL")->execute([$invoiceId,$id,$bid]);$pdo->commit();audit('quotation.convert',$quote['quotation_number'].' → '.$invoiceNumber);flash('Accepted quotation converted to invoice.');redirect('invoice-view.php?id='.$invoiceId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Quotation conversion could not be completed.','error');return;}
  }
  if($act==='create'){
   $customerId=(int)($_POST['customer_id']??0);$cq=$pdo->prepare('SELECT * FROM customers WHERE id=? AND business_id=? AND archived_at IS NULL');$cq->execute([$customerId,$bid]);$customer=$cq->fetch();$descriptions=$_POST['description']??[];$quantities=$_POST['quantity']??[];$rates=$_POST['rate']??[];$taxes=$_POST['tax_rate']??[];$lines=[];$subtotal=0;$taxTotal=0;foreach($descriptions as $i=>$description){$description=trim((string)$description);$qty=(float)($quantities[$i]??0);$rate=max(0,(float)($rates[$i]??0));$tax=max(0,min(100,(float)($taxes[$i]??0)));if($description===''||$qty<=0)continue;$base=round($qty*$rate,2);$taxValue=round($base*$tax/100,2);$lines[]=['description'=>mb_substr($description,0,255),'quantity'=>$qty,'rate'=>$rate,'tax'=>$tax,'subtotal'=>$base,'tax_value'=>$taxValue];$subtotal+=$base;$taxTotal+=$taxValue;}if(!$customer||!$lines){flash('Choose an active customer and add at least one valid line item.','error');return;}try{$pdo->beginTransaction();$date=post_text('quotation_date',10)?:date('Y-m-d');$valid=post_text('valid_until',10)?:null;$businessQ=$pdo->prepare('SELECT * FROM businesses WHERE id=?');$businessQ->execute([$bid]);$business=$businessQ->fetch();$number='QUO-'.date('Y').'-'.bin2hex(random_bytes(4));$pdo->prepare('INSERT INTO quotations(business_id,customer_id,quotation_number,quotation_date,valid_until,status,subtotal,tax_total,total,customer_snapshot,business_snapshot,notes) VALUES(?,?,?,?,?,\'Draft\',?,?,?,?,?,?)')->execute([$bid,$customerId,$number,$date,$valid,$subtotal,$taxTotal,round($subtotal+$taxTotal,2),json_encode($customer),json_encode($business),post_text('notes',4000)]);$quotationId=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO quotation_items(quotation_id,description,quantity,unit,unit_price,tax_rate,line_subtotal,line_tax,line_total) VALUES(?,?,?,?,?,?,?,?,?)');foreach($lines as $line)$insert->execute([$quotationId,$line['description'],$line['quantity'],'unit',$line['rate'],$line['tax'],$line['subtotal'],$line['tax_value'],$line['subtotal']+$line['tax_value']]);$pdo->commit();audit('quotation.create',$number);flash('Quotation saved as a draft.');redirect('quotation-view.php?id='.$quotationId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Quotation could not be saved.','error');return;}
  }
 }
}
function module_css(string $type): void { echo '<style>.section-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:19px}.section-head h1{font:700 24px var(--display);margin:3px 0}.section-head p{margin:0;color:#8b96a3;font-size:11px}.content-card{background:#fff;border:1px solid #edf0f2;border-radius:9px;padding:17px}.toolbar{display:flex;gap:9px;align-items:center;margin-bottom:13px}.search{height:35px;border:1px solid #e8ebef;border-radius:6px;padding:0 10px;min-width:220px;font-size:11px;outline:none}.data-table th{padding:10px}.data-table td{padding:12px 10px;font-size:10px}.table-action{color:#358fca;font-weight:600}.inline-form{display:inline}.link-button{border:0;background:none;color:#328ec8;cursor:pointer;font-size:10px;padding:3px}.modal-form{display:grid;grid-template-columns:1fr 1fr;gap:11px}.modal-form .wide{grid-column:1/-1}.modal-form label{font-size:10px;color:#596574;font-weight:600}.modal-form input,.modal-form select,.modal-form textarea{display:block;width:100%;margin-top:5px;height:36px;border:1px solid #e5e9ed;border-radius:6px;padding:0 9px;font-size:11px}.modal-form textarea{height:72px;padding:8px}.record-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.detail-line{padding:10px 0;border-bottom:1px solid #f0f2f4;font-size:11px}.detail-line span{display:inline-block;color:#8e99a4;width:110px}.pill{display:inline-block;background:#eff5f8;border-radius:12px;padding:4px 8px;font-size:9px;color:#6d7e8c}.status-form{display:flex;gap:5px;align-items:center}.status-form select{font-size:9px;border:1px solid #e8edf0;border-radius:5px;padding:4px}.summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0}.summary-tile{padding:14px;border:1px solid #edf0f2;border-radius:8px}.summary-tile small{display:block;color:#98a2ac;font-size:9px}.summary-tile strong{display:block;font:700 18px var(--display);margin-top:4px}.simple-form{max-width:700px}.help-text{font-size:10px;color:#99a3ad}@media(max-width:650px){.section-head{align-items:flex-start;gap:12px;flex-direction:column}.record-grid{grid-template-columns:1fr}.modal-form,.summary-grid{grid-template-columns:1fr}.modal-form .wide{grid-column:auto}.search{min-width:0;width:100%}.toolbar{align-items:stretch;flex-direction:column}}</style>'; }
function section_head(string $eyebrow,string $title,string $desc,string $button,string $href): void { echo '<div class="section-head"><div><span class="eyebrow">'.e($eyebrow).'</span><h1>'.e($title).'</h1><p>'.e($desc).'</p></div><a class="button primary" href="'.e($href).'"><i class="ti ti-plus"></i> '.e($button).'</a></div>'; }
function modal_form(string $title,string $action,string $fields,string $button='Save'): void { echo '<dialog id="record-modal"><form method="post" class="content-card" style="width:min(620px,90vw);border:0"><div class="panel-head" style="margin-bottom:14px"><h2>'.e($title).'</h2><button type="button" class="link-button" onclick="document.getElementById(\'record-modal\').close()">Close</button></div><input type="hidden" name="_csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'"><div class="modal-form">'.$fields.'</div><div style="display:flex;justify-content:flex-end;margin-top:15px"><button class="button primary">'.e($button).'</button></div></form></dialog>'; }
